- private fun editDistanceSimilarity(s1: String, s2: String): Float {
- val distance = levenshteinDistance(s1, s2)
- val maxLength = maxOf(s1.length, s2.length)
- return if (maxLength == 0) 1f else 1f - (distance.toFloat() / maxLength)
- }
