0.1f\n }\n\n override suspend fun findSimilarOrders(\n orderQuery: String,\n customerQuery: String?,\n candidates: List<Order>,\n maxResults: Int\n ): Result<List<Pair<Order, Float>>> = withContext(Dispatchers.IO) {\n Log.d(TAG, \"=== Starting order fuzzy matching ===\")\n Log.d(TAG, \"Order query: '$orderQuery'\")\n Log.d(TAG, \"Customer query: '$customerQuery'\")\n Log.d(TAG, \"Candidates: ${candidates.size} orders\")\n val startTime = System.currentTimeMillis()\n try {\n if (candidates.isEmpty()) {\n Log.w(TAG, \"\\u274c No order candidates provided\")\n return@withContext Result.success(emptyList())\n }\n val processedOrderQuery = preprocessOrderNumber(orderQuery)\n val processedCustomerQuery = customerQuery?.let { preprocessCustomerName(it) }\n Log.d(TAG, \"Preprocessed order query: '$processedOrderQuery'\")\n Log.d(TAG, \"Preprocessed customer query: '$processedCustomerQuery'\")\n val similarities = mutableListOf<Pair<Order, Float>>()\n for (order in candidates) {\n val orderSimilarity = calculateOrderNumberSimilarity(processedOrderQuery, order.number)\n val customerSimilarity = if (processedCustomerQuery != null) {\n calculateCustomerNameSimilarity(processedCustomerQuery, order.tradingPartnerDescription)\n } else {\n 0.5f // Neutral score when no customer specified\n }\n val totalSimilarity = (orderSimilarity * ORDER_NUMBER_WEIGHT) + (customerSimilarity * CUSTOMER_NAME_WEIGHT)\n if (totalSimilarity > ORDER_SIMILARITY_THRESHOLD) {\n similarities.add(Pair(order, totalSimilarity))\n Log.v(TAG,\"Order ${order.number}: orderSim=\" +\n String.format(\"%.3f\", orderSimilarity) +\n \", customerSim=\" + String.format(\"%.3f\", customerSimilarity) +\n \", total=\" + String.format(\"%.3f\", totalSimilarity))\n }\n }\n val topMatches = similarities.sortedByDescending { it.second }.take(maxResults)\n val totalDuration = System.currentTimeMillis() - startTime\n Log.d(TAG, \"\\u2705 Order fuzzy matching completed in ${totalDuration}ms\")\n Log.d(TAG, \"Found ${topMatches.size} matches above threshold $ORDER_SIMILARITY_THRESHOLD\")\n topMatches.forEachIndexed { index, (order, similarity) ->\n Log.d(TAG, \" ${index + 1}. ${order.number} (${order.tradingPartnerDescription}) - score: ${String.format(\"%.3f\", similarity)}\")\n }\n Log.d(TAG, \"=== Order fuzzy matching completed ===\")\n Result.success(topMatches)\n } catch (e: Exception) {\n val totalDuration = System.currentTimeMillis() - startTime\n Log.e(TAG, \"\\u274c Order fuzzy matching failed after ${totalDuration}ms\", e)\n Result.failure(e)\n }\n }\n\n override suspend fun findSimilarItems(\n query: String,\n candidates: List<MasterItem>,\n maxResults: Int\n ): Result<List<MasterItem>> = withContext(Dispatchers.IO) {\n Log.d(TAG, \"=== Starting fast AI-based fuzzy matching ===\")\n Log.d(TAG, \"Query: '$query'\")\n Log.d(TAG, \"Candidates: ${candidates.size} items\")\n val startTime = System.currentTimeMillis()\n try {\n if (candidates.isEmpty()) {\n Log.w(TAG, \"\\u274c No candidates provided\")\n return@withContext Result.success(emptyList())\n }\n val processedQuery = preprocessText(query)\n Log.d(TAG, \"Preprocessed query: '$processedQuery'\")\n val similarities = mutableListOf<Pair<MasterItem, Float>>()\n val uniqueDescriptions = candidates.map { it.description }.distinct()\n val descriptionScores = mutableMapOf<String, Float>()\n Log.d(TAG, \"Processing ${uniqueDescriptions.size} unique descriptions...\")\n for (description in uniqueDescriptions) {\n val similarity = calculateAISimilarity(processedQuery, description)\n descriptionScores[description] = similarity\n }\n for (item in candidates) {\n val similarity = descriptionScores[item.description] ?: 0f\n if (similarity > ITEM_SIMILARITY_THRESHOLD) {\n similarities.add(Pair(item, similarity))\n }\n }\n val topMatches = similarities.sortedByDescending { it.second }.take(maxResults).map { it.first }\n val totalDuration = System.currentTimeMillis() - startTime\n Log.d(TAG, \"\\u2705 Fast AI fuzzy matching completed in ${totalDuration}ms\")\n Log.d(TAG, \"Found ${topMatches.size} matches above threshold $ITEM_SIMILARITY_THRESHOLD\")\n topMatches.forEachIndexed { index, item ->\n val similarity = similarities.find { it.first.code == item.code }?.second ?: 0f\n Log.d(TAG, \" ${index + 1}. ${item.code}: ${item.description} (score: ${ \"%.3f\".format(similarity) })\")\n }\n Log.d(TAG, \"=== Fast AI fuzzy matching completed ===\")\n Result.success(topMatches)\n } catch (e: Exception) {\n val totalDuration = System.currentTimeMillis() - startTime\n Log.e(TAG, \"\\u274c Fast AI fuzzy matching failed after ${totalDuration}ms\", e)\n Result.failure(e)\n }\n }\n\n // All helper methods from OrderFuzzyMatchClient and FastFuzzyMatchClient below\n // Strictly preserved\n // ... ORDER HELPER METHODS ...\n private fun preprocessOrderNumber(orderNumber: String): String {\n return orderNumber.uppercase().replace(Regex(\"[^A-Z0-9]\"), \"\").trim()\n }\n private fun preprocessCustomerName(customerName: String): String {\n return customerName.lowercase().replace(Regex(\"[^a-z0-9\\\\s]\"), \" \").replace(Regex(\"\\\\s+\"), \" \").trim()\n }\n private fun calculateOrderNumberSimilarity(query: String, candidate: String): Float {\n val processedCandidate = preprocessOrderNumber(candidate)\n if (query.equals(processedCandidate, ignoreCase = true)) return 1.0f\n val phoneticSim = calculateOrderPhoneticSimilarity(query, processedCandidate)\n val structuralSim = calculateOrderStructuralSimilarity(query, processedCandidate)\n val contextualSim = calculateOrderContextualSimilarity(query, processedCandidate)\n val totalScore = (phoneticSim * ORDER_PHONETIC_WEIGHT) + (structuralSim * ORDER_STRUCTURAL_WEIGHT) + (contextualSim * ORDER_CONTEXTUAL_WEIGHT)\n val boostFactor = calculateOrderBoostFactor(query, processedCandidate)\n val finalScore = minOf(1.0f, totalScore * boostFactor)\n return finalScore\n }\n private fun calculateCustomerNameSimilarity(query: String, candidate: String): Float {\n val processedCandidate = preprocessCustomerName(candidate)\n if (query.equals(processedCandidate, ignoreCase = true)) return 1.0f\n if (query.contains(processedCandidate, ignoreCase = true) || processedCandidate.contains(query, ignoreCase = true)) return 0.9f\n return calculateCustomerWordSimilarity(query, processedCandidate)\n }\n private fun calculateOrderPhoneticSimilarity(query: String, candidate: String): Float {\n val queryNumbers = extractNumbers(query)\n val candidateNumbers = extractNumbers(candidate)\n val queryAlpha = extractAlpha(query)\n val candidateAlpha = extractAlpha(candidate)\n val numberSim = if (queryNumbers.isNotEmpty() && candidateNumbers.isNotEmpty()) {\n calculateNumberPhoneticSimilarity(queryNumbers, candidateNumbers)\n } else { 0.5f }\n val alphaSim = if (queryAlpha.isNotEmpty() && candidateAlpha.isNotEmpty()) {\n calculateAlphaPhoneticSimilarity(queryAlpha, candidateAlpha)\n } else { 0.5f }\n return (numberSim * 0.7f) + (alphaSim * 0.3f)\n }\n private fun calculateOrderStructuralSimilarity(query: String, candidate: String): Float {\n val lengthSim = 1f - abs(query.length - candidate.length).toFloat() / maxOf(query.length, candidate.length)\n val patternSim = calculateOrderPatternSimilarity(query, candidate)\n val charSim = calculateCharacterOverlap(query, candidate)\n return (lengthSim * 0.2f) + (patternSim * 0.5f) + (charSim * 0.3f)\n }\n private fun calculateOrderContextualSimilarity(query: String, candidate: String): Float {\n val queryNumbers = extractNumbers(query)\n val candidateNumbers = extractNumbers(candidate)\n if (queryNumbers.isEmpty() || candidateNumbers.isEmpty()) return 0.3f\n val rangeSim = calculateNumberRangeSimilarity(queryNumbers, candidateNumbers)\n val sequenceSim = calculateDigitSequenceSimilarity(query, candidate)\n return (rangeSim * 0.6f) + (sequenceSim * 0.4f)\n }\n private fun calculateOrderBoostFactor(query: String, candidate: String): Float {\n val queryNumbers = extractNumbers(query)\n val candidateNumbers = extractNumbers(candidate)\n if (queryNumbers.isNotEmpty() && candidateNumbers.isNotEmpty()) {\n val exactNumberMatch = queryNumbers.intersect(candidateNumbers.toSet()).isNotEmpty()\n if (exactNumberMatch) return 1.3f\n }\n val editDistance = calculateLevenshteinDistance(query, candidate)\n val maxLength = maxOf(query.length, candidate.length)\n val editSimilarity = 1f - (editDistance.toFloat() / maxLength)\n return when {\n editSimilarity >= 0.8f -> 1.2f\n editSimilarity >= 0.6f -> 1.1f\n else -> 1.0f\n }\n }\n private fun calculateCustomerWordSimilarity(query: String, candidate: String): Float {\n val queryWords = query.split(\"\\\\s+\".toRegex()).filter { it.length > 1 }\n val candidateWords = candidate.split(\"\\\\s+\".toRegex()).filter { it.length > 1 }\n if (queryWords.isEmpty() || candidateWords.isEmpty()) return 0f\n val exactMatches = queryWords.count { queryWord -> candidateWords.any { candidateWord -> queryWord.equals(candidateWord, ignoreCase = true) } }\n val partialMatches = queryWords.count { queryWord -> candidateWords.any { candidateWord -> !queryWord.equals(candidateWord, ignoreCase = true) && (candidateWord.startsWith(queryWord, ignoreCase = true) || queryWord.startsWith(candidateWord, ignoreCase = true) || calculateLevenshteinDistance(queryWord, candidateWord) <= 2 ) } }\n val exactRatio = exactMatches.toFloat() / queryWords.size\n val partialRatio = (partialMatches.toFloat() / queryWords.size) * 0.7f\n return exactRatio + partialRatio\n }\n private fun extractNumbers(text: String): List<String> {\n return Regex(\"\\\\d+\").findAll(text).map { it.value }.toList()\n }\n private fun extractAlpha(text: String): String {\n return text.replace(Regex(\"\\\\d\"), \"\")\n }\n private fun calculateNumberPhoneticSimilarity(queryNumbers: List<String>, candidateNumbers: List<String>): Float {\n var bestMatch = 0f\n for (queryNum in queryNumbers) {\n for (candidateNum in candidateNumbers) {\n val similarity = when {\n queryNum == candidateNum -> 1.0f\n queryNum.startsWith(candidateNum