import android.util.Log
import com.example.granitevoice.domain.model.Order
import com.example.granitevoice.domain.model.MasterItem
import com.example.granitevoice.domain.repository.FuzzyMatchingRepository
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlin.math.*

class FuzzyMatchingRepositoryImpl : FuzzyMatchingRepository {
 private val TAG = "FuzzyMatchingRepositoryImpl"

 // ========== ORDER FUZZY MATCHING LOGIC ==========
 companion object {
 private const val ORDER_SIMILARITY_THRESHOLD = 0.4f // Slightly lower for orders
 private const val ORDER_NUMBER_WEIGHT = 0.7f // Order number is most important
 private const val CUSTOMER_NAME_WEIGHT = 0.3f // Customer name is secondary
 private const val ORDER_PHONETIC_WEIGHT = 0.4f
 private const val ORDER_STRUCTURAL_WEIGHT = 0.3f
 private const val ORDER_CONTEXTUAL_WEIGHT = 0.3f

 // ========== ITEM / MASTER ITEM FUZZY MATCHING ==========
 private const val ITEM_SIMILARITY_THRESHOLD = 0.3f
 private const val ITEM_PHONETIC_WEIGHT = 0.3f
 private const val ITEM_SEMANTIC_WEIGHT = 0.4f
 private const val ITEM_STRUCTURAL_WEIGHT = 0.2f
 private const val ITEM_CONTEXTUAL_WEIGHT = 0.1f
 }

 override suspend fun findSimilarOrders(
 orderQuery: String,
 customerQuery: String?,
 candidates: List<Order>,
 maxResults: Int
 ): Result<List<Pair<Order, Float>>> = withContext(Dispatchers.IO) {
 Log.d(TAG, "=== Starting order fuzzy matching ===")
 Log.d(TAG, "Order query: '$orderQuery'")
 Log.d(TAG, "Customer query: '$customerQuery'")
 Log.d(TAG, "Candidates: ${candidates.size} orders")
 val startTime = System.currentTimeMillis()
 try {
 if (candidates.isEmpty()) {
 Log.w(TAG, "\u274c No order candidates provided")
 return@withContext Result.success(emptyList())
 }
 val processedOrderQuery = preprocessOrderNumber(orderQuery)
 val processedCustomerQuery = customerQuery?.let { preprocessCustomerName(it) }
 Log.d(TAG, "Preprocessed order query: '$processedOrderQuery'")
 Log.d(TAG, "Preprocessed customer query: '$processedCustomerQuery'")
 val similarities = mutableListOf<Pair<Order, Float>>()
 for (order in candidates) {
 val orderSimilarity =
 calculateOrderNumberSimilarity(processedOrderQuery, order.number)
 val customerSimilarity = if (processedCustomerQuery != null) {
 calculateCustomerNameSimilarity(
 processedCustomerQuery,
 order.tradingPartnerDescription
 )
 } else {
 0.5f // Neutral score when no customer specified
 }
 val totalSimilarity =
 (orderSimilarity * ORDER_NUMBER_WEIGHT) + (customerSimilarity * CUSTOMER_NAME_WEIGHT)
 if (totalSimilarity > ORDER_SIMILARITY_THRESHOLD) {
 similarities.add(Pair(order, totalSimilarity))
 Log.v(
 TAG, "Order ${order.number}: orderSim=" +
 String.format("%.3f", orderSimilarity) +
 ", customerSim=" + String.format("%.3f", customerSimilarity) +
 ", total=" + String.format("%.3f", totalSimilarity)
 )
 }
 }
 val topMatches = similarities.sortedByDescending { it.second }.take(maxResults)
 val totalDuration = System.currentTimeMillis() - startTime
 Log.d(TAG, "\u2705 Order fuzzy matching completed in ${totalDuration}ms")
 Log.d(
 TAG,
 "Found ${topMatches.size} matches above threshold $ORDER_SIMILARITY_THRESHOLD"
 )
 topMatches.forEachIndexed { index, (order, similarity) ->
 Log.d(
 TAG,
 " ${index + 1}. ${order.number} (${order.tradingPartnerDescription}) - score: ${
 String.format(
 "%.3f",
 similarity
 )
 }"
 )
 }
 Log.d(TAG, "=== Order fuzzy matching completed ===")
 Result.success(topMatches)
 } catch (e: Exception) {
 val totalDuration = System.currentTimeMillis() - startTime
 Log.e(TAG, "\u274c Order fuzzy matching failed after ${totalDuration}ms", e)
 Result.failure(e)
 }
 }

 override suspend fun findSimilarItems(
 query: String,
 candidates: List<MasterItem>,
 maxResults: Int
 ): Result<List<MasterItem>> = withContext(Dispatchers.IO) {
 Log.d(TAG, "=== Starting fast AI-based fuzzy matching ===")
 Log.d(TAG, "Query: '$query'")
 Log.d(TAG, "Candidates: ${candidates.size} items")
 val startTime = System.currentTimeMillis()
 try {
 if (candidates.isEmpty()) {
 Log.w(TAG, "\u274c No candidates provided")
 return@withContext Result.success(emptyList())
 }
 val processedQuery = preprocessText(query)
 Log.d(TAG, "Preprocessed query: '$processedQuery'")
 val similarities = mutableListOf<Pair<MasterItem, Float>>()
 val uniqueDescriptions = candidates.map { it.description }.distinct()
 val descriptionScores = mutableMapOf<String, Float>()
 Log.d(TAG, "Processing ${uniqueDescriptions.size} unique descriptions...")
 for (description in uniqueDescriptions) {
 val similarity = calculateAISimilarity(processedQuery, description)
 descriptionScores[description] = similarity
 }
 for (item in candidates) {
 val similarity = descriptionScores[item.description] ?: 0f
 if (similarity > ITEM_SIMILARITY_THRESHOLD) {
 similarities.add(Pair(item, similarity))
 }
 }
 val topMatches =
 similarities.sortedByDescending { it.second }.take(maxResults).map { it.first }
 val totalDuration = System.currentTimeMillis() - startTime
 Log.d(TAG, "\u2705 Fast AI fuzzy matching completed in ${totalDuration}ms")
 Log.d(
 TAG,
 "Found ${topMatches.size} matches above threshold $ITEM_SIMILARITY_THRESHOLD"
 )
 topMatches.forEachIndexed { index, item ->
 val similarity = similarities.find { it.first.code == item.code }?.second ?: 0f
 Log.d(
 TAG,
 " ${index + 1}. ${item.code}: ${item.description} (score: ${
 "%.3f".format(similarity)
 })"
 )
 }
 Log.d(TAG, "=== Fast AI fuzzy matching completed ===")
 Result.success(topMatches)
 } catch (e: Exception) {
 val totalDuration = System.currentTimeMillis() - startTime
 Log.e(TAG, "\u274c Fast AI fuzzy matching failed after ${totalDuration}ms", e)
 Result.failure(e)
 }
 }

 // All helper methods from OrderFuzzyMatchClient and FastFuzzyMatchClient below
 // Strictly preserved
 private fun preprocessOrderNumber(orderNumber: String): String {
 return orderNumber.uppercase().replace(Regex("[^A-Z0-9]"), "").trim()
 }

 private fun preprocessCustomerName(customerName: String): String {
 return customerName.lowercase().replace(Regex("[^a-z0-9\\s]"), " ")
 .replace(Regex("\\s+"), " ").trim()
 }

 private fun calculateOrderNumberSimilarity(query: String, candidate: String): Float {
 val processedCandidate = preprocessOrderNumber(candidate)
 if (query.equals(processedCandidate, ignoreCase = true)) return 1.0f
 val phoneticSim = calculateOrderPhoneticSimilarity(query, processedCandidate)
 val structuralSim = calculateOrderStructuralSimilarity(query, processedCandidate)
 val contextualSim = calculateOrderContextualSimilarity(query, processedCandidate)
 val totalScore =
 (phoneticSim * ORDER_PHONETIC_WEIGHT) + (structuralSim * ORDER_STRUCTURAL_WEIGHT) + (contextualSim * ORDER_CONTEXTUAL_WEIGHT)
 val boostFactor = calculateOrderBoostFactor(query, processedCandidate)
 val finalScore = minOf(1.0f, totalScore * boostFactor)
 return finalScore
 }

 private fun calculateCustomerNameSimilarity(query: String, candidate: String): Float {
 val processedCandidate = preprocessCustomerName(candidate)
 if (query.equals(processedCandidate, ignoreCase = true)) return 1.0f
 if (query.contains(processedCandidate, ignoreCase = true) || processedCandidate.contains(
 query,
 ignoreCase = true
 )
 ) return 0.9f
 return calculateCustomerWordSimilarity(query, processedCandidate)
 }

 private fun calculateOrderPhoneticSimilarity(query: String, candidate: String): Float {
 val queryNumbers = extractNumbers(query)
 val candidateNumbers = extractNumbers(candidate)
 val queryAlpha = extractAlpha(query)
 val candidateAlpha = extractAlpha(candidate)
 val numberSim = if (queryNumbers.isNotEmpty() && candidateNumbers.isNotEmpty()) {
 calculateNumberPhoneticSimilarity(queryNumbers, candidateNumbers)
 } else {
 0.5f
 }
 val alphaSim = if (queryAlpha.isNotEmpty() && candidateAlpha.isNotEmpty()) {
 calculateAlphaPhoneticSimilarity(queryAlpha, candidateAlpha)
 } else {
 0.5f
 }
 return (numberSim * 0.7f) + (alphaSim * 0.3f)
 }

 private fun calculateOrderStructuralSimilarity(query: String, candidate: String): Float {
 val lengthSim = 1f - abs(query.length - candidate.length).toFloat() / maxOf(
 query.length,
 candidate.length
 )
 val patternSim = calculateOrderPatternSimilarity(query, candidate)
 val charSim = calculateCharacterOverlap(query, candidate)
 return (lengthSim * 0.2f) + (patternSim * 0.5f) + (charSim * 0.3f)
 }

 private fun calculateOrderContextualSimilarity(query: String, candidate: String): Float {
 val queryNumbers = extractNumbers(query)
 val candidateNumbers = extractNumbers(candidate)
 if (queryNumbers.isEmpty() || candidateNumbers.isEmpty()) return 0.3f
 val rangeSim = calculateNumberRangeSimilarity(queryNumbers, candidateNumbers)
 val sequenceSim = calculateDigitSequenceSimilarity(query, candidate)
 return (rangeSim * 0.6f) + (sequenceSim * 0.4f)
 }

 private fun calculateOrderBoostFactor(query: String, candidate: String): Float {
 val queryNumbers = extractNumbers(query)
 val candidateNumbers = extractNumbers(candidate)
 if (queryNumbers.isNotEmpty() && candidateNumbers.isNotEmpty()) {
 val exactNumberMatch = queryNumbers.intersect(candidateNumbers.toSet()).isNotEmpty()
 if (exactNumberMatch) return 1.3f
 }
 val editDistance = calculateLevenshteinDistance(query, candidate)
 val maxLength = maxOf(query.length, candidate.length)
 val editSimilarity = 1f - (editDistance.toFloat() / maxLength)
 return when {
 editSimilarity >= 0.8f -> 1.2f
 editSimilarity >= 0.6f -> 1.1f
 else -> 1.0f
 }
 }

 private fun calculateCustomerWordSimilarity(query: String, candidate: String): Float {
 val queryWords = query.split("\\s+".toRegex()).filter { it.length > 1 }
 val candidateWords = candidate.split("\\s+".toRegex()).filter { it.length > 1 }
 if (queryWords.isEmpty() || candidateWords.isEmpty()) return 0f
 val exactMatches = queryWords.count { queryWord ->
 candidateWords.any { candidateWord ->
 queryWord.equals(
 candidateWord,
 ignoreCase = true
 )
 }
 }
 val partialMatches = queryWords.count { queryWord ->
 candidateWords.any { candidateWord ->
 !queryWord.equals(
 candidateWord,
 ignoreCase = true
 ) && (candidateWord.startsWith(
 queryWord,
 ignoreCase = true
 ) || queryWord.startsWith(
 candidateWord,
 ignoreCase = true
 ) || calculateLevenshteinDistance(queryWord, candidateWord) <= 2)
 }
 }
 val exactRatio = exactMatches.toFloat() / queryWords.size
 val partialRatio = (partialMatches.toFloat() / queryWords.size) * 0.7f
 return exactRatio + partialRatio
 }

 private fun extractNumbers(text: String): List<String> {
 return Regex("\\d+").findAll(text).map { it.value }.toList()
 }

 private fun extractAlpha(text: String): String {
 return text.replace(Regex("\\d"), "")
 }

 private fun calculateNumberPhoneticSimilarity(
 queryNumbers: List<String>,
 candidateNumbers: List<String>
 ): Float {
 var bestMatch = 0f
 for (queryNum in queryNumbers) {
 for (candidateNum in candidateNumbers) {
 val similarity = when {
 queryNum == candidateNum -> 1.0f
 queryNum.startsWith(candidateNum) || candidateNum.startsWith(queryNum) -> 0.8f
 calculateDigitSimilarity(queryNum, candidateNum) > 0.5f -> 0.7f
 else -> 0f
 }
 bestMatch = maxOf(bestMatch, similarity)
 }
 }
 return bestMatch
 }

 private fun calculateAlphaPhoneticSimilarity(
 queryAlpha: String,
 candidateAlpha: String
 ): Float {
 return when {
 queryAlpha == candidateAlpha -> 1.0f
 queryAlpha.startsWith(candidateAlpha) || candidateAlpha.startsWith(queryAlpha) -> 0.8f
 calculateLevenshteinDistance(queryAlpha, candidateAlpha) <= 2 -> 0.6f
 else -> 0.3f
 }
 }

 private fun calculateOrderPatternSimilarity(query: String, candidate: String): Float {
 val queryPattern = getOrderPattern(query)
 val candidatePattern = getOrderPattern(candidate)
 return if (queryPattern == candidatePattern) 1.0f else 0.5f
 }

 private fun getOrderPattern(orderNumber: String): String {
 return orderNumber.map { char ->
 when {
 char.isLetter() -> 'A'
 char.isDigit() -> 'N'
 else -> 'X'
 }
 }.joinToString("")
 }

 private fun calculateCharacterOverlap(query: String, candidate: String): Float {
 val queryChars = query.groupingBy { it }.eachCount()
 val candidateChars = candidate.groupingBy { it }.eachCount()
 val commonChars = queryChars.keys.intersect(candidateChars.keys)
 if (commonChars.isEmpty()) return 0f
 var overlap = 0
 for (char in commonChars) {
 overlap += minOf(queryChars[char]!!, candidateChars[char]!!)
 }
 val totalChars = maxOf(query.length, candidate.length)
 return overlap.toFloat() / totalChars
 }

 private fun calculateNumberRangeSimilarity(
 queryNumbers: List<String>,
 candidateNumbers: List<String>
 ): Float {
 var bestSimilarity = 0f
 for (queryNum in queryNumbers) {
 for (candidateNum in candidateNumbers) {
 val qNum = queryNum.toIntOrNull() ?: continue
 val cNum = candidateNum.toIntOrNull() ?: continue
 val similarity = when {
 qNum == cNum -> 1.0f
 abs(qNum - cNum) <= 1 -> 0.9f
 abs(qNum - cNum) <= 10 -> 0.7f
 abs(qNum - cNum) <= 100 -> 0.5f
 else -> 0f
 }
 bestSimilarity = maxOf(bestSimilarity, similarity)
 }
 }
 return bestSimilarity
 }

 private fun calculateDigitSequenceSimilarity(query: String, candidate: String): Float {
 val queryDigits = query.filter { it.isDigit() }
 val candidateDigits = candidate.filter { it.isDigit() }
 if (queryDigits.isEmpty() || candidateDigits.isEmpty()) return 0f
 return calculateLevenshteinSimilarity(queryDigits, candidateDigits)
 }

 private fun calculateDigitSimilarity(num1: String, num2: String): Float {
 return calculateLevenshteinSimilarity(num1, num2)
 }

 private fun calculateLevenshteinSimilarity(s1: String, s2: String): Float {
 val distance = calculateLevenshteinDistance(s1, s2)
 val maxLength = maxOf(s1.length, s2.length)
 return if (maxLength == 0) 1f else 1f - (distance.toFloat() / maxLength)
 }

 private fun calculateLevenshteinDistance(s1: String, s2: String): Int {
 val dp = Array(s1.length + 1) { IntArray(s2.length + 1) }
 for (i in 0..s1.length) dp[i][0] = i
 for (j in 0..s2.length) dp[0][j] = j
 for (i in 1..s1.length) {
 for (j in 1..s2.length) {
 if (s1[i - 1] == s2[j - 1]) {
 dp[i][j] = dp[i - 1][j - 1]
 } else {
 dp[i][j] = 1 + minOf(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
 }
 }
 }
 return dp[s1.length][s2.length]
 }

 // ... ITEM / MASTER ITEM FUZZY HELPERS ...
 private fun preprocessText(text: String): String {
 return text.lowercase().replace(Regex("[^a-z0-9x.\\s]"), " ").replace(Regex("\\s+"), " ")
 .trim()
 }

 private fun calculateAISimilarity(query: String, candidate: String): Float {
 val processedCandidate = preprocessText(candidate)
 if (query.equals(processedCandidate, ignoreCase = true)) return 1.0f
 val phoneticSim = phoneticSimilarity(query, processedCandidate)
 val semanticSim = semanticSimilarity(query, processedCandidate)
 val structuralSim = structuralSimilarity(query, processedCandidate)
 val contextSim = contextualSimilarity(query, processedCandidate)
 val totalScore =
 (phoneticSim * ITEM_PHONETIC_WEIGHT) + (semanticSim * ITEM_SEMANTIC_WEIGHT) + (structuralSim * ITEM_STRUCTURAL_WEIGHT) + (contextSim * ITEM_CONTEXTUAL_WEIGHT)
 val boostFactor = calculateBoostFactor(query, processedCandidate)
 val finalScore = minOf(1.0f, totalScore * boostFactor)
 return finalScore
 }

 private fun calculateBoostFactor(query: String, candidate: String): Float {
 val queryWords = query.split(" ").filter { it.length > 1 }
 val candidateWords = candidate.split(" ").filter { it.length > 1 }
 if (queryWords.isEmpty() || candidateWords.isEmpty()) return 1.0f
 val exactMatches = queryWords.count { word1 ->
 candidateWords.any { word2 ->
 word1.equals(
 word2,
 ignoreCase = true
 )
 }
 }
 val partialMatches = queryWords.count { queryWord ->
 candidateWords.any { candidateWord ->
 !queryWord.equals(
 candidateWord,
 ignoreCase = true
 ) && (areNumbersSimilar(
 queryWord,
 candidateWord
 ) || (queryWord.length > 2 && candidateWord.length > 2 && queryWord.take(3)
 .equals(candidateWord.take(3), ignoreCase = true)))
 }
 }
 val exactRatio = exactMatches.toFloat() / queryWords.size
 val partialRatio = partialMatches.toFloat() / queryWords.size
 val combinedRatio = exactRatio + (partialRatio * 0.7f)
 return when {
 exactRatio >= 0.8f -> 1.4f
 exactRatio >= 0.6f -> 1.3f
 combinedRatio >= 0.8f -> 1.25f
 exactRatio >= 0.4f -> 1.15f
 combinedRatio >= 0.6f -> 1.1f
 else -> 1.0f
 }
 }

 private fun areNumbersSimilar(word1: String, word2: String): Boolean {
 val numbers1 = Regex("\\d+").findAll(word1).map { it.value.toIntOrNull() ?: 0 }.toList()
 val numbers2 = Regex("\\d+").findAll(word2).map { it.value.toIntOrNull() ?: 0 }.toList()
 if (numbers1.isEmpty() || numbers2.isEmpty()) return false
 return numbers1.any { num1 ->
 numbers2.any { num2 ->
 num1 == num2 ||
 (num1 >= 100 && num2 >= 10 && num1.toString().take(2) == num2.toString()
 .take(2)) ||
 (num1.toString().length >= 3 && num2.toString().length >= 3 && num1.toString()
 .take(3) == num2.toString().take(3)) ||
 kotlin.math.abs(num1 - num2) <= 10
 }
 }
 }

 private fun phoneticSimilarity(text1: String, text2: String): Float {
 val words1 = text1.split(" ").filter { it.isNotEmpty() }
 val words2 = text2.split(" ").filter { it.isNotEmpty() }
 if (words1.isEmpty() || words2.isEmpty()) return 0f
 var totalSim = 0f
 var matches = 0
 for (word1 in words1) {
 val bestMatch =
 words2.maxOfOrNull { word2 -> phoneticWordSimilarity(word1, word2) } ?: 0f
 totalSim += bestMatch
 matches++
 }
 return if (matches > 0) totalSim / matches else 0f
 }

 private fun phoneticWordSimilarity(word1: String, word2: String): Float {
 val soundex1 = getSoundex(word1)
 val soundex2 = getSoundex(word2)
 if (soundex1 == soundex2) return 1.0f
 val commonChars = soundex1.zip(soundex2).count { it.first == it.second }
 return commonChars.toFloat() / maxOf(soundex1.length, soundex2.length)
 }

 private fun getSoundex(word: String): String {
 if (word.isEmpty()) return "0000"
 val soundexMap = mapOf(
 'b' to '1',
 'f' to '1',
 'p' to '1',
 'v' to '1',
 'c' to '2',
 'g' to '2',
 'j' to '2',
 'k' to '2',
 'q' to '2',
 's' to '2',
 'x' to '2',
 'z' to '2',
 'd' to '3',
 't' to '3',
 'l' to '4',
 'm' to '5',
 'n' to '5',
 'r' to '6'
 )
 val firstChar = word.first().uppercaseChar()
 val digits = word.drop(1).map { soundexMap[it.lowercaseChar()] ?: '0' }.filter { it != '0' }
 .distinct().take(3).joinToString("").padEnd(3, '0')
 return "$firstChar$digits"
 }

 private fun semanticSimilarity(text1: String, text2: String): Float {
 val words1 = text1.split(" ").filter { it.length > 1 }
 val words2 = text2.split(" ").filter { it.length > 1 }
 if (words1.isEmpty() || words2.isEmpty()) return 0f
 val exactMatches =
 words1.count { word1 -> words2.any { word2 -> word1.equals(word2, ignoreCase = true) } }
 val totalWords = words1.size
 val exactMatchRatio = exactMatches.toFloat() / totalWords
 val abbreviationMatches = words1.count { word1 ->
 words2.any { word2 ->
 isAbbreviationMatch(
 word1,
 word2
 ) || word1.contains(word2, ignoreCase = true) || word2.contains(
 word1,
 ignoreCase = true
 )
 }
 }
 val abbrevMatchRatio = (abbreviationMatches.toFloat() / totalWords) * 0.8f
 var semanticMatch = 0f
 var pairs = 0
 for (word1 in words1) {
 for (word2 in words2) {
 if (!word1.equals(word2, ignoreCase = true)) {
 semanticMatch += getSemanticWordSimilarity(word1, word2)
 pairs++
 }
 }
 }
 val avgSemantic = if (pairs > 0) (semanticMatch / pairs) * 0.5f else 0f
 return maxOf(exactMatchRatio, abbrevMatchRatio + avgSemantic)
 }

 private fun isAbbreviationMatch(word1: String, word2: String): Boolean {
 val shorter = if (word1.length < word2.length) word1 else word2
 val longer = if (word1.length >= word2.length) word1 else word2
 return when {
 shorter.length < 2 -> false
 longer.startsWith(shorter, ignoreCase = true) -> true
 shorter.startsWith(longer, ignoreCase = true) -> true
 (shorter.equals("usp", true) && longer.equals("usps", true)) -> true
 (shorter.equals("usps", true) && longer.equals("usp", true)) -> true
 else -> false
 }
 }

 private fun getSemanticWordSimilarity(word1: String, word2: String): Float {
 return when {
 word1.take(4) == word2.take(4) && minOf(word1.length, word2.length) >= 4 -> 0.8f
 word1.take(3) == word2.take(3) && minOf(word1.length, word2.length) >= 3 -> 0.6f
 isSemanticPair(word1, word2) -> 0.7f
 else -> {
 val editSim = editDistanceSimilarity(word1, word2)
 if (editSim > 0.6f) editSim * 0.5f else 0f
 }
 }
 }

 private fun isSemanticPair(word1: String, word2: String): Boolean {
 val pairs = setOf(
 setOf("box", "container"), setOf("screw", "bolt"), setOf("nail", "fastener"),
 setOf("hammer", "tool"), setOf("drill", "tool"), setOf("saw", "tool"),
 setOf("wood", "lumber"), setOf("metal", "steel"), setOf("plastic", "polymer"),
 setOf("red", "crimson"), setOf("blue", "navy"), setOf("green", "emerald"),
 setOf("small", "mini"), setOf("large", "big"), setOf("long", "extended"),
 setOf("pipe", "tube"), setOf("wire", "cable"), setOf("sheet", "panel")
 )
 val wordSet = setOf(word1, word2)
 return pairs.any { it == wordSet }
 }

 private fun structuralSimilarity(text1: String, text2: String): Float {
 val lengthSim =
 1f - abs(text1.length - text2.length).toFloat() / maxOf(text1.length, text2.length)
 val patternSim = characterPatternSimilarity(text1, text2)
 return (lengthSim * 0.3f) + (patternSim * 0.7f)
 }

 private fun characterPatternSimilarity(text1: String, text2: String): Float {
 val chars1 = text1.groupingBy { it }.eachCount()
 val chars2 = text2.groupingBy { it }.eachCount()
 val allChars = (chars1.keys + chars2.keys).toSet()
 var similarity = 0f
 for (char in allChars) {
 val count1 = chars1[char] ?: 0
 val count2 = chars2[char] ?: 0
 if (maxOf(count1, count2) > 0) {
 similarity += minOf(count1, count2).toFloat() / maxOf(count1, count2)
 }
 }
 return similarity / allChars.size
 }

 private fun contextualSimilarity(text1: String, text2: String): Float {
 val numberSim = numberPatternSimilarity(text1, text2)
 val positionSim = positionalSimilarity(text1, text2)
 return (numberSim * 0.6f) + (positionSim * 0.4f)
 }

 private fun numberPatternSimilarity(text1: String, text2: String): Float {
 val pattern1 = Regex("\\d+(?:[x-]\\d+|\\.\\d+)?").findAll(text1).map { it.value }.toSet()
 val pattern2 = Regex("\\d+(?:[x-]\\d+|\\.\\d+)?").findAll(text2).map { it.value }.toSet()
 if (pattern1.isEmpty() && pattern2.isEmpty()) return 1f
 if (pattern1.isEmpty() || pattern2.isEmpty()) return 0f
 val exactMatches = pattern1.intersect(pattern2)
 if (exactMatches.isNotEmpty()) {
 return exactMatches.size.toFloat() / pattern1.union(pattern2).size
 }
 var similarMatches = 0
 for (p1 in pattern1) {
 for (p2 in pattern2) {
 if (areNumberPatternsSimilar(p1, p2)) {
 similarMatches++
 break
 }
 }
 }
 return if (similarMatches > 0) {
 (similarMatches.toFloat() / pattern1.union(pattern2).size) * 0.8f
 } else {
 0f
 }
 }

 private fun areNumberPatternsSimilar(pattern1: String, pattern2: String): Boolean {
 val nums1 = Regex("\\d+").findAll(pattern1).map { it.value.toIntOrNull() ?: 0 }.toList()
 val nums2 = Regex("\\d+").findAll(pattern2).map { it.value.toIntOrNull() ?: 0 }.toList()
 if (nums1.isEmpty() || nums2.isEmpty()) return false
 return nums1.any { num1 ->
 nums2.any { num2 ->
 num1 == num2 ||
 (num1 >= 100 && num2 >= 10 && num1.toString().take(2) == num2.toString()
 .take(2)) ||
 (num1.toString().length >= 3 && num2.toString().length >= 3 && num1.toString()
 .take(3) == num2.toString().take(3)) ||
 kotlin.math.abs(num1 - num2) <= 5
 }
 }
 }

 private fun positionalSimilarity(text1: String, text2: String): Float {
 val minLength = minOf(text1.length, text2.length)
 if (minLength == 0) return 0f
 var matches = 0
 for (i in 0 until minLength) {
 if (text1[i] == text2[i]) matches++
 }
 return matches.toFloat() / maxOf(text1.length, text2.length)
 }

 private fun editDistanceSimilarity(s1: String, s2: String): Float {
 val distance = calculateLevenshteinDistance(s1, s2)
 val maxLength = maxOf(s1.length, s2.length)
 return if (maxLength == 0) 1f else 1f - (distance.toFloat() / maxLength)
 }
}
