+
+ private fun preprocessOrderNumber(orderNum: String): String {
+ return orderNum.trim().lowercase().replace("""\s+""".toRegex(), "")
+ }
+
+ private fun preprocessCustomerName(name: String): String {
+ return name.trim().lowercase().replace("""\s+""".toRegex(), " ")
+ }
+
+ private fun calculateOrderNumberSimilarity(query: String, candidate: String): Float {
+ val normQuery = preprocessOrderNumber(query)
+ val normCandidate = preprocessOrderNumber(candidate)
+ // Fast path for exact match
+ if (normQuery == normCandidate) return 1f
+ // Compute edit distance similarity
+ val levSim = levenshteinSimilarity(normQuery, normCandidate)
+ // Also check prefix/suffix match
+ val prefixBonus = if (normCandidate.startsWith(normQuery)) 0.2f else 0f
+ val suffixBonus = if (normCandidate.endsWith(normQuery)) 0.15f else 0f
+ return (levSim + prefixBonus + suffixBonus).coerceAtMost(1f)
+ }
+
+ private fun calculateCustomerNameSimilarity(query: String, candidate: String): Float {
+ val normQuery = preprocessCustomerName(query)
+ val normCandidate = preprocessCustomerName(candidate)
+ // Fast path for exact match
+ if (normQuery == normCandidate) return 1f
+ // Compute edit distance similarity
+ val levSim = levenshteinSimilarity(normQuery, normCandidate)
+ // Loose substring match bonus
+ val substringBonus = if (normCandidate.contains(normQuery)) 0.18f else 0f
+ return (levSim + substringBonus).coerceAtMost(1f)
+ }
+
+ private fun levenshteinSimilarity(str1: String, str2: String): Float {
+ val maxLen = max(str1.length, str2.length)
+ if (maxLen == 0) return 1f
+ val dist = levenshtein(str1, str2)
+ // Convert distance to similarity from 0.0 to 1.0
+ return 1f - (dist.toFloat() / maxLen)
+ }
+
+ // Classic Levenshtein implementation (for small strings)
+ private fun levenshtein(lhs: String, rhs: String): Int {
+ val lhsLen = lhs.length
+ val rhsLen = rhs.length
+ val dp = IntArray(rhsLen + 1) { it }
+ for (i in 1..lhsLen) {
+ var last = i - 1
+ dp[0] = i
+ for (j in 1..rhsLen) {
+ val cost = if (lhs[i - 1] == rhs[j - 1]) 0 else 1
+ val value = minOf(
+ dp[j] + 1,
+ dp[j - 1] + 1,
+ last + cost
+ )
+ last = dp[j]
+ dp[j] = value
+ }
+ }
+ return dp[rhsLen]
+ }
 }

